class ValidationChain {
  constructor(fields, locations) {
    this.fields = Array.isArray(fields) ? fields : [fields];
    this.locations = locations;
    this.checks = [];
  }

  trim() {
    this.checks.push((val) => (typeof val === 'string' ? val.trim() : val));
    return this;
  }

  notEmpty() {
    this.currentCheck = (val) => val !== undefined && val !== null && String(val).trim().length > 0;
    this.currentMsg = 'Field cannot be empty';
    this.checks.push({ fn: this.currentCheck, msg: this.currentMsg });
    return this;
  }

  isEmail() {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    this.currentCheck = (val) => typeof val === 'string' && emailRegex.test(val.trim());
    this.currentMsg = 'Invalid email address';
    this.checks.push({ fn: this.currentCheck, msg: this.currentMsg });
    return this;
  }

  normalizeEmail() {
    this.checks.push((val) => (typeof val === 'string' ? val.toLowerCase().trim() : val));
    return this;
  }

  isLength(options = {}) {
    this.currentCheck = (val) => {
      const len = val ? String(val).length : 0;
      if (options.min !== undefined && len < options.min) return false;
      if (options.max !== undefined && len > options.max) return false;
      return true;
    };
    this.currentMsg = `Length must be between ${options.min || 0} and ${options.max || Infinity}`;
    this.checks.push({ fn: this.currentCheck, msg: this.currentMsg });
    return this;
  }

  withMessage(msg) {
    if (this.checks.length > 0) {
      const last = this.checks[this.checks.length - 1];
      if (typeof last === 'object') {
        last.msg = msg;
      }
    }
    return this;
  }

  async run(req) {
    const errors = [];
    for (const field of this.fields) {
      let val = req.body ? req.body[field] : undefined;
      for (const check of this.checks) {
        if (typeof check === 'function') {
          val = check(val);
          if (req.body) req.body[field] = val;
        } else if (check && typeof check.fn === 'function') {
          const ok = check.fn(val);
          if (!ok) {
            errors.push({
              type: 'field',
              value: val,
              msg: check.msg,
              path: field,
              location: 'body'
            });
            break; // Stop checking this field on first failure
          }
        }
      }
    }
    return errors;
  }
}

export function body(fields) {
  const chain = new ValidationChain(fields, ['body']);
  const middleware = async (req, res, next) => {
    const errs = await chain.run(req);
    if (!req._validationErrors) req._validationErrors = [];
    req._validationErrors.push(...errs);
    next();
  };

  // Attach chain methods directly to middleware function
  Object.getOwnPropertyNames(ValidationChain.prototype).forEach((m) => {
    if (m !== 'constructor' && m !== 'run') {
      middleware[m] = (...args) => {
        chain[m](...args);
        return middleware;
      };
    }
  });

  return middleware;
}

export function validationResult(req) {
  const errors = req._validationErrors || [];
  return {
    isEmpty: () => errors.length === 0,
    array: () => errors
  };
}

export default {
  body,
  validationResult
};
